   "resumen": "Las ballenas jorobadas no solo defienden a sus crías de las orcas: también suelen intervenir cuando estas atacan a otras especies, como las focas. Así lo concluye un estudio publicado en Marine Mammal Science, en el que un equipo liderado por Robert Pitman analizó más de 100…",
