   "sintesis": "EST Guardar La Universidad Internacional de La Rioja (UNIR) celebró este jueves el 'Summit Perú 2026: Liderazgo Público en la Era de la Inteligencia Artificial', un encuentro académico internacional que convirtió a la ciudad imperial en punto de encuentro para autoridades, expertos y académicos de distintos países comprometidos con la modernización de la gestión pública. El evento, desarrollado en la Capilla de San Antonio Abad del Monasterio Belmond Hotel de Cusco, tuvo como objetivo promover el intercambio de experiencias internacionales y fortalecer las capacidades de los servidores públicos frente a los desafíos y oportunidades que plantea la inteligencia artificial.",
