   "resumen": "La Presidencia del Consejo de Ministros establece seis objetivos estratégicos para prevenir y responder a incidentes de seguridad digital, proteger la infraestructura crítica y fortalecer las capacidades tecnológicas del país",
   "fuente": "La Mula",
   "url": "https://redaccion.lamula.pe/2026/11/24/peru-aprueba-estrategia-nacional-de-ciberseguridad-2026-2030-para-proteger-sistemas-digitales-y-servicios-publicos-esenciales/redaccionmulera/",
